  function stonepineExpeditionState(){player.expeditions=player.expeditions&&typeof player.expeditions==='object'?player.expeditions:{};player.expeditions.stonepine=normalizeStonepineExpedition(player.expeditions.stonepine);return player.expeditions.stonepine;}
  function ensureStonepineLedger(){if(!Array.isArray(world.landmarks))world.landmarks=[];let ledger=world.landmarks.find(l=>l.id==='stonepine-trail-ledger');if(!ledger){ledger={id:'stonepine-trail-ledger',name:'Stonepine Trail Ledger',x:1115,y:760,r:16,discovered:true,playerOnly:true};world.landmarks.push(ledger);}else{ledger.name='Stonepine Trail Ledger';ledger.x=1115;ledger.y=760;ledger.discovered=true;ledger.playerOnly=true;}return ledger;}
