  function stonepineExpeditionNext(progress=stonepineExpeditionProgress()){if(!progress.overlook)return'Chart Stonepine Overlook';if(!progress.cache)return'Secure the Stonepine Waycache';if(progress.bread<1)return'Store 1 Brown Bread in the Waycache';if(progress.arrows<6)return`Store ${6-progress.arrows} more Trail Arrow${6-progress.arrows===1?'':'s'} in the Waycache`;return'Return to the Trail Ledger in Briar Glen';}
  function visitStonepineLedger(l=ensureStonepineLedger()){if(!l||dist(player,l)>55){toast('Return to the Stonepine Trail Ledger in Briar Glen');return false;}const state=stonepineExpeditionState();if(state.completed){toast('Stonepine expedition complete · route proven');return true;}if(!state.started){state.started=true;log('You opened a Stonepine expedition in the Trail Ledger: chart the Overlook, secure and provision the Waycache, then return to Briar Glen.','world');save();renderUI();toast('Stonepine expedition started · chart · secure · provision · return');return true;}const progress=stonepineExpeditionProgress();if(!progress.ready){toast(`Stonepine expedition · ${stonepineExpeditionNext(progress)}`);return false;}state.completed=true;state.rewarded=true;player.coins+=18;skillXp('fieldcraft',10);log('Stonepine expedition complete: the ridge route is charted, its Waycache provisioned, and the return to Briar Glen recorded.','world');save();renderUI();toast('Stonepine expedition complete · 18c · Fieldcraft +10 XP');return true;}
