  function npcSafety(n){if(n.goal!=='patrol')return;const call=activeDangerReport();if(!call){n.think=0;return;}if(call.enemy.type==='emberback'){n.goal='guard';n.target={...n.work};n.goalText='Holding Briar Glen while Emberback controls the quarry';n.think=5;if(!n.memory.some(m=>m.text.includes('Emberback is beyond routine patrol')))memory(n,'Emberback is beyond routine patrol; the quarry stays blocked until someone brings it down.');return;}const blade=npcArtifactState(n,'blade');if(!blade||blade.durability<=0){n.needBias.blade=Math.max(n.needBias.blade||0,6);n.goal='gear';n.target={...n.work};n.goalText='Cannot answer danger without a usable Warden Blade';n.request=requestFor(n);n.think=0;return;}n.target={x:call.enemy.x,y:call.enemy.y};if(dist(n,call.enemy)>55)return;call.enemy.dead=true;n.injury=clamp(Math.max(0,Number(n.injury||0))+28,0,100);memory(n,'The patrol left me bruised; Field Tonic would help me recover.');const wear=Math.max(4,Math.round(12-(blade.quality-1)*3));blade.durability=Math.max(0,blade.durability-wear);blade.provenance.history.push(`Used by Tamsin to clear danger for ${call.reporter.name} on Day ${world.day}.`);if(blade.provenance.history.length>8)blade.provenance.history.shift();creditPlayerMadeUse(n,'blade',blade,'keeping the road open');const maker=blade.provenance.maker==='You'?'the blade you forged':`${blade.provenance.maker}'s blade`;memory(n,`Cleared a wolf that was blocking ${call.reporter.name}'s work with ${maker}.`);memory(call.reporter,`Tamsin cleared the wolf that stopped my work.`);relation(call.reporter,n,.35);relation(n,call.reporter,.2);call.reporter.blockedByDanger=null;call.reporter.think=0;if(blade.durability<=0){n.needBias.blade=Math.max(n.needBias.blade||0,6);memory(n,'My Warden Blade broke while keeping the road open.');}log(`Tamsin drove off a wolf so ${call.reporter.name} could get back to work.`,'npc');n.think=0;}
  function socialDelivery(n){if(n.goal!=='deliver'||!n.socialCommitment)return false;const commitment=n.socialCommitment,requester=npcs.find(x=>x.id===commitment.requesterId),id=commitment.itemId;if(requester&&isArtifact(id)&&npcArtifactReady(requester,id)){requester.brokeredNeed=null;n.socialCommitment=null;n.think=0;return false;}if(!requester||(n.stock?.[id]||0)<1){breakSocialPromise(n,!requester?'the requester was unavailable':'the promised stock was gone');return false;}n.target={x:requester.x,y:requester.y};if(dist(n,requester)>50)return false;const transferredArtifact=isArtifact(id)?copy(npcArtifactState(n,id)):null;let deliveredQuality=transferredArtifact?.quality||1;if(isArtifact(id)){n.stock[id]--;requester.stock[id]=1;if(transferredArtifact){requester.stockMeta??={};requester.stockMeta[id]=recordArtifactTransfer(transferredArtifact,n.name,requester.name,'promised delivery');if(n.stock[id]<=0)delete n.stockMeta[id];}}else{const quality=npcRemoveStack(n,id,1);if(quality==null){breakSocialPromise(n,'the promised stock was gone');return false;}deliveredQuality=quality;npcAddStack(requester,id,1,quality);}n.trades=(n.trades||0)+1;requester.trades=(requester.trades||0)+1;promiseReliability(n).kept+=1;const qualityBond=clamp((deliveredQuality-1)*.06,0,.12);relation(requester,n,.45+qualityBond);relation(n,requester,.3+qualityBond*.5);requester.trust=clamp(requester.trust+.35,0,10);n.trust=clamp(n.trust+.2,0,10);memory(requester,`${n.name} kept the ${itemDefs[id].name} promise you brokered. It was ${qualityLabel(deliveredQuality)} quality.`);memory(n,`I kept my ${itemDefs[id].name} promise to ${requester.name} after you connected us. It was ${qualityLabel(deliveredQuality)} quality.`);log(`${n.name} delivered ${itemDefs[id].name} to ${requester.name} because of your introduction.`,'npc');requester.brokeredNeed=null;n.socialCommitment=null;requester.request=requestFor(requester);n.request=requestFor(n);requester.think=0;n.think=0;save();return true;}

  function canShareCheckInMedicine(donor,recipient){const history=careHistory(donor,recipient),recentReciprocity=history.careReceived>0&&history.lastReceivedDay>0&&world.day-history.lastReceivedDay<=7;return (donor.stock?.tonic||0)>1&&(donor.injury||0)<20&&(recipient.injury||0)>=20&&(recipient.stock?.tonic||0)<1&&(relationValue(donor,recipient)>=1||recentReciprocity)&&canCooperate(donor,recipient)&&!donor.socialCommitment;}
  function medicineCareTarget(n){if(n.energy<45||n.hunger>55)return null;return npcs.filter(other=>other!==n&&canShareCheckInMedicine(n,other)).sort((a,b)=>(b.injury-a.injury)||(relationValue(n,b)-relationValue(n,a))||(dist(n,a)-dist(n,b)))[0]||null;}
  function shareCheckInMedicine(a,b){const pair=[[a,b],[b,a]].find(([donor,recipient])=>canShareCheckInMedicine(donor,recipient));if(!pair)return false;const [donor,recipient]=pair,quality=npcRemoveStack(donor,'tonic',1);if(quality==null)return false;npcAddStack(recipient,'tonic',1,quality);recordCareHistory(donor,recipient);relation(recipient,donor,.2);relation(donor,recipient,.1);memory(donor,`I shared a spare ${qualityLabel(quality)} Field Tonic with ${recipient.name} when I saw they were hurt.`);memory(recipient,`${donor.name} noticed I was hurt and shared a spare ${qualityLabel(quality)} Field Tonic without being asked.`);log(`${donor.name} shared spare medicine with ${recipient.name} during their check-in.`,'npc');return true;}
  function completeSocialCheckIn(n){if(n.goal!=='social'||!n.socialTargetId)return false;const other=npcs.find(x=>x.id===n.socialTargetId);if(!other){n.socialTargetId=null;n.think=0;return false;}n.target={x:other.x+25,y:other.y};n.goalText=`Checking in with ${other.name}`;if(dist(n,other)>50)return false;shareCheckInMedicine(n,other);n.mood=clamp(Math.max(50,n.mood+12),0,100);other.mood=clamp(other.mood+5,0,100);relation(n,other,.1);relation(other,n,.08);memory(n,`${other.name} took time to check in with me; I feel steadier.`);memory(other,`${n.name} came to check in; we had a good talk.`);log(`${n.name} checked in with ${other.name}; the conversation lifted their spirits.`,'npc');n.socialTargetId=null;n.goal='idle';n.goalText='Feeling steadier after a good conversation';n.target={x:n.x,y:n.y};n.think=4;return true;}

  function updateNPC(n,dt){n.relations??={};n.productionCooldown=Math.max(0,(n.productionCooldown||0)-dt);n.exchangeCooldown=Math.max(0,(n.exchangeCooldown||0)-dt);n.think=(n.think||0)-dt;n.hunger=clamp(n.hunger+dt*.45,0,100);const physicallyResting=n.goal==='sleep'&&dist(n,n.home)<=12;n.energy=clamp(n.energy-dt*(physicallyResting?-2.5:.18),0,100);n.mood=clamp(n.mood+dt*((n.hunger<55?1:-1)*.08),0,100);if(n.think<=0){chooseNpcGoal(n);n.think=rand(3,7);}if(n.goal==='seek'&&n.seekSource){const supplier=npcs.find(x=>x.id===n.seekSource);if(supplier)n.target={x:supplier.x,y:supplier.y};}if(n.goal==='seekSmith'&&n.seekSource){const smith=npcs.find(x=>x.id===n.seekSource);if(smith){n.target={x:smith.x,y:smith.y};const service=damagedArtifactForNpc(n);n.goalText=service?`Taking ${itemDefs[service.id].name} to ${smith.name} for service`:'Seeking the resident smith';}else{n.seekSource=null;n.think=0;}}if(n.goal==='deliver'&&n.socialCommitment){const requester=npcs.find(x=>x.id===n.socialCommitment.requesterId);if(requester)n.target={x:requester.x,y:requester.y};}if(n.goal==='seekService'&&n.seekingServiceFor){const service=damagedArtifactForNpc(n),call=n.serviceCall,elapsed=call?.itemId===n.seekingServiceFor?Math.max(0,worldMinuteStamp()-Number(call.startStamp||worldMinuteStamp())):0;if(!service){n.seekingServiceFor=null;n.serviceCall=null;n.think=0;}else if(elapsed>180){missSmithServiceCall(n,'I waited too long for service')}else if(dist(n,player)>65){n.target={x:player.x,y:player.y};n.goalText=`Seeking you to service ${itemDefs[n.seekingServiceFor].name}`;}else{n.target={x:n.x,y:n.y};n.goalText=`Waiting for you to service ${itemDefs[n.seekingServiceFor].name}`;}}if(n.goal==='seekProvider'&&n.seekingProviderFor){const req=n.request||requestFor(n),call=n.providerCall,elapsed=call?Math.max(0,worldMinuteStamp()-Number(call.startStamp||worldMinuteStamp())):0;if(!req||req.id!==n.seekingProviderFor){n.seekingProviderFor=null;n.providerCall=null;n.think=0;}else if(elapsed>300){missProviderCall(n,'I waited and you never came through');}else if(dist(n,player)>65){n.target={x:player.x,y:player.y};n.goalText=`Seeking you for ${itemDefs[n.seekingProviderFor].name}`;}else{n.target={x:n.x,y:n.y};n.goalText=itemCount(req.id)>=req.qty?`Waiting for your ${itemDefs[n.seekingProviderFor].name}`:`Waiting while you source ${itemDefs[n.seekingProviderFor].name}`;}}if(n.goal==='refer'&&n.pendingReferral){const recipient=npcs.find(x=>x.id===n.pendingReferral.recipientId);if(recipient){n.target={x:recipient.x,y:recipient.y};n.goalText=n.pendingReferral.kind==='provider'?`Going to tell ${recipient.name} you supply ${itemDefs[n.pendingReferral.itemId]?.name||'needed goods'}`:`Going to tell ${recipient.name} about your Smithing`;}else{n.pendingReferral=null;n.think=0;}}if(n.goal==='patrol'){const call=activeDangerReport();if(call)n.target={x:call.enemy.x,y:call.enemy.y};else n.think=0;}if(n.goal==='social'&&n.socialTargetId){const other=npcs.find(x=>x.id===n.socialTargetId);if(other){n.target={x:other.x+25,y:other.y};n.goalText=`Checking in with ${other.name}`;}else{n.socialTargetId=null;n.think=0;}}const dx=n.target.x-n.x,dy=n.target.y-n.y,d=Math.hypot(dx,dy);if(d>4){const injuryFactor=1-clamp(Math.max(0,Number(n.injury||0))/500,0,.15),speed=(n.goal==='sleep'?65:45)*(world.weather==='rain'?.93:1)*injuryFactor;n.x+=dx/d*speed*dt;n.y+=dy/d*speed*dt;}deliverSmithReferral(n);deliverProviderReferral(n);completeSocialCheckIn(n);socialDelivery(n);npcSafety(n);npcEconomy(n);}

  function priceFor(n,id,mode='buy'){const def=itemDefs[id],need=npcNeedScore(n,id),stock=n.stock[id]||0,trust=n.trust;let p=def.base*(1+need*.12)*(1+Math.max(0,2-stock)*.08);if(mode==='sell')p*=.62+Math.min(.18,trust*.01);else p*=1.2-Math.min(.18,trust*.01);return Math.max(1,Math.round(p));}
  function helpNPC(n){const r=n.request||requestFor(n);if(!r){toast(`${n.name} has no urgent request`);return false;}if(itemCount(r.id)<r.qty){toast(`Need ${r.qty} ${itemDefs[r.id].name}`);return false;}const q=avgQuality(r.id),artifact=isArtifact(r.id)?artifactSnapshot(r.id):null;removeItem(r.id,r.qty);if(artifact){recordArtifactTransfer(artifact,'You',n.name,'request fulfilled');n.stock[r.id]=1;n.stockMeta??={};n.stockMeta[r.id]=artifact;n.seekSource=null;n.productionPlan=null;n.routeOverride=null;n.goal='idle';n.target={...n.work};n.think=0;}else npcAddStack(n,r.id,r.qty,q);n.trust=clamp(n.trust+1+Math.max(0,q-1)*.4+(artifact?.provenance?.maker==='You'?.25:0),0,10);const providerPremium=providerReliabilityPremium(n,r.id,r.reward);player.coins+=r.reward+Math.round((q-1)*3)+providerPremium;n.lastPlayerHelp=world.day;recordProviderExperience(n,r.id,r.qty,q);const answeredProviderCall=completeProviderCall(n,r.id)!=null;n.seekingProviderFor=null;if(answeredProviderCall&&n.goal==='seekProvider'){n.goal='idle';n.goalText='Supply received';n.target={...n.work};n.think=0;}memory(n,artifact?.provenance?.maker==='You'?`You brought the ${qualityLabel(q)} ${itemDefs[r.id].name} you made on Day ${artifact.provenance.madeDay} when it was needed.${r.reputationAtCreation?` I asked because you are known for ${r.reputationAtCreation}.`:''}`:`You brought ${r.qty} ${itemDefs[r.id].name} when it was needed.${r.reputationAtCreation?` I asked because you are known for ${r.reputationAtCreation}.`:''}`);if(providerPremium>0){memory(n,`I paid ${providerPremium}c extra because you answered when I came looking for you.`);log(`${n.name} paid ${providerPremium}c extra for reliable repeat service.`,'npc');}skillXp('rapport',8);deriveIdentity();toast(providerPremium>0?`${n.name} remembers that help · +${providerPremium}c reliability premium`:`${n.name} remembers that help`);log(`${n.name}'s shortage eased because you brought ${itemDefs[r.id].name}.`,'npc');n.request=null;save();return true;}
  function sellToNPC(n){const need=topNeed(n);const id=need.id;if(itemCount(id)<1){toast(`You have no ${itemDefs[id].name}`);return false;}const price=priceFor(n,id,'sell'),q=avgQuality(id),artifact=isArtifact(id)?artifactSnapshot(id):null;removeItem(id,1);if(artifact){recordArtifactTransfer(artifact,'You',n.name,'sale');n.stock[id]=1;n.stockMeta??={};n.stockMeta[id]=artifact;}else npcAddStack(n,id,1,q);player.coins+=Math.round(price*q);n.trust=clamp(n.trust+.15+(artifact?.provenance?.maker==='You'?.15:0),0,10);memory(n,artifact?.provenance?.maker==='You'?`Bought the ${qualityLabel(q)} ${itemDefs[id].name} you made.`:`Bought ${itemDefs[id].name} from you.`);deriveIdentity();save();toast(`Sold ${itemDefs[id].name} for ${Math.round(price*q)}c`);return true;}
  function reservedProfessionGear(n,id){return professionTools[n.role]===id||npcs.some(owner=>owner.id!==n.id&&professionTools[owner.role]===id&&(owner.stock?.[id]||0)<1);}
  function buyFromNPC(n){const entries=Object.entries(n.stock).filter(([id,q])=>q>0&&itemDefs[id]&&!reservedProfessionGear(n,id)&&(!isArtifact(id)||itemCount(id)===0));if(!entries.length){toast(`${n.name} has nothing spare you can carry`);return false;}entries.sort((a,b)=>priceFor(n,a[0],'buy')-priceFor(n,b[0],'buy'));const [id]=entries[0],artifact=isArtifact(id)?copy(npcArtifactState(n,id)):null,q=artifact?.quality||npcStackQuality(n,id);const price=Math.round(priceFor(n,id,'buy')*q);if(player.coins<price){toast(`Need ${price}c`);return false;}player.coins-=price;if(isArtifact(id)){recordArtifactTransfer(artifact,n.name,'You','purchase');n.stock[id]--;if(n.stock[id]<=0&&n.stockMeta)delete n.stockMeta[id];}else npcRemoveStack(n,id,1);addItem(id,1,q,artifact||{maker:n.name,source:`${n.name}'s stock`});save();toast(`Bought ${itemDefs[id].name} for ${price}c`);return true;}

  function townNeedState(){const out={food:0,medicine:0,metal:0,materials:0};for(const n of npcs){for(const id of Object.keys(n.needBias||{})){const score=npcNeedScore(n,id),kind=itemDefs[id]?.kind;if(kind==='food')out.food+=score;else if(kind==='medicine'||kind==='herb')out.medicine+=score;else if(kind==='ore'||kind==='tool'||kind==='weapon')out.metal+=score;else out.materials+=score;}}world.townNeeds=out;return out;}
  function dominantTownNeed(){const needs=townNeedState(),[key,value]=Object.entries(needs).sort((a,b)=>b[1]-a[1])[0];return{key,value,label:{food:'food',medicine:'medicine and herbs',metal:'metal and tools',materials:'field materials'}[key]};}
  function deriveIdentity(){const totalTrust=npcs.reduce((s,n)=>s+n.trust,0),helped=npcs.filter(n=>n.trust>=1).length,craft=player.skills.smithing.level+player.skills.herbcraft.level,makerImpact=Math.max(0,Number(player.makerImpact||0)),field=player.skills.fieldcraft.level,guard=player.skills.guard.level,emberbackDeed=player.deeds?.emberback?1:0,publicStanding=totalTrust+emberbackDeed*4;player.standing=publicStanding>=16?'Mainstay':publicStanding>=9?'Trusted':publicStanding>=4?'Known':'Unknown';const scores=[['keeping people supplied',totalTrust+helped*2],['keeping the Glen’s gear working',(player.servicesCompleted||0)*3+player.skills.smithing.level*2],['making useful things',makerImpact>0?makerImpact*5+Math.max(0,craft-2):0],['bringing back what the Glen needs',field*2],['keeping the roads safe',guard*2+emberbackDeed*8]];scores.sort((a,b)=>b[1]-a[1]);player.knownFor=scores[0][1]>4?scores[0][0]:'nothing yet';}

  function resourceGatherQuality(node){const zone=zoneAt(node.x,node.y),weatherBonus=world.weather==='rain'&&itemDefs[node.type].kind==='herb'?.18:0,quarryBonus=player.deeds?.emberback&&node.type==='iron'&&zone?.id==='quarry'?.25:0,ridgeBonus=zone?.id==='ridge'&&(node.type==='iron'||node.type==='wood')?.3:0;return clamp(node.quality+weatherBonus+quarryBonus+ridgeBonus,.7,3);}
  function resourceQualityCause(node){const causes=[],zone=zoneAt(node.x,node.y);if(world.weather==='rain'&&itemDefs[node.type].kind==='herb')causes.push('rain-enriched');if(player.deeds?.emberback&&node.type==='iron'&&zone?.id==='quarry')causes.push('reopened seam');if(zone?.id==='ridge'&&(node.type==='iron'||node.type==='wood'))causes.push('high-ridge yield');return causes.join(' · ');}
  function gather(node){if(!node.available)return false;const pick=player.inventory.pick,pickReady=player.equippedTool==='pick'&&pick?.durability>0,pickQuality=pickReady?avgQuality('pick'):1;let q=resourceGatherQuality(node)+(player.skills.fieldcraft.level-1)*.12;let qty=1;if(node.type==='iron'){if(pickReady){qty+=player.skills.fieldcraft.level>=3?1:0;q+=(pickQuality-1)*.18;pick.durability=Math.max(0,pick.durability-Math.max(2,6-Math.floor(pickQuality)));}else q-=.35;}if(node.type==='wood'&&pickReady)q-=.2;addItem(node.type,qty,clamp(q,.7,3));node.available=false;node.respawn=rand(60,120);player.energy=Math.max(0,player.energy-(node.type==='iron'?(pickReady?8:12):4));skillXp('fieldcraft',node.type==='iron'?5:3);if(player.equippedTool==='pick'&&pick&&!pick.durability)toast('Iron Pick broke — Mend it before the next hard job');save();return true;}
  function craft(id){const r=recipes[id];if(!r)return false;if(player.skills[r.skill].level<r.level){toast(`${skillDefs[r.skill].name} ${r.level} required`);return false;}if((isArtifact(id)||id==='bedroll')&&itemCount(id)>0){toast(id==='bedroll'?'You already carry a Trail Bedroll.':`You already carry a ${itemDefs[id].name}; singular gear keeps its own history.`);return false;}if(!hasItems(r.input)){toast(`Missing materials for ${itemDefs[id].name}`);return false;}let total=0,count=0;for(const [mat,q] of Object.entries(r.input)){total+=avgQuality(mat)*q;count+=q;}const materialQuality=total/count;consume(r.input);const quality=clamp(materialQuality+(player.skills[r.skill].level-1)*.15,.8,3),forged=r.skill==='smithing',craftVerb=forged?'Forged':'Crafted';const artifact=isArtifact(id)?{provenance:{maker:'You',madeDay:world.day,source:forged?'Player-forged':'Player-crafted',materialQuality,skillLevel:player.skills[r.skill].level,repairs:0,history:[`${craftVerb} by You on Day ${world.day} from ${qualityLabel(materialQuality)} materials.`]}}:null;const outputQty=Math.max(1,Number(r.qty||1));if(!addItem(id,outputQty,quality,artifact))return false;skillXp(r.skill,10);if(itemDefs[id]?.kind==='tool')player.equippedTool=id;if(itemDefs[id]?.kind==='weapon')player.equippedWeapon=id;if(itemDefs[id]?.kind==='armor')player.equippedArmor=id;deriveIdentity();save();toast(`Crafted ${qualityLabel(quality)} ${itemDefs[id].name}${outputQty>1?` ×${outputQty}`:''}`);return true;}
  function drinkTonic(){if(itemCount('tonic')<1){toast('No Field Tonic');return false;}if(player.hp>=player.maxHp){toast('Health is already full — save the Field Tonic');return false;}const quality=avgQuality('tonic'),base=35+player.skills.herbcraft.level*3,qualityDelta=Math.round(clamp(quality-1,-.5,2)*6),heal=Math.max(1,base+qualityDelta),before=player.hp;removeItem('tonic',1);player.hp=clamp(player.hp+heal,0,player.maxHp);const restored=player.hp-before;save();toast(`${qualityLabel(quality)} Field Tonic restored ${restored} health${restored<heal?' · fully recovered':''}`);return true;}
  function eatBread(){if(itemCount('bread')<1){toast('No Brown Bread for the trail');return false;}if(player.energy>=player.maxEnergy-10){toast('Energy is already high — save the bread for the trail');return false;}const quality=avgQuality('bread'),restore=Math.max(12,Math.round(30+clamp(quality-1,-.5,2)*8)),before=player.energy;removeItem('bread',1);player.energy=clamp(player.energy+restore,0,player.maxEnergy);const restored=player.energy-before;save();log(`You ate ${qualityLabel(quality)} Brown Bread at Stonepine Overlook and recovered ${Math.round(restored)} energy.`,'world');toast(`${qualityLabel(quality)} Brown Bread restored ${Math.round(restored)} energy`);return true;}

  function campDanger(range=180){return world.enemies.find(e=>!e.dead&&dist(player,e)<=range)||null;}
  function makeCamp(){
    const zone=zoneAt(player.x,player.y);
    if(!zone||zone.id==='village'){toast('Make camp in the wilderness, not Briar Glen');return false;}
    if(itemCount('bedroll')<1){toast('Craft a Trail Bedroll before making camp');return false;}
    const danger=campDanger();
    if(danger){toast(`${danger.name||'Danger'} is too close to make camp`);return false;}
    if(itemCount('bread')<1){toast('Camp needs 1 Brown Bread provision');return false;}
    const breadQuality=avgQuality('bread'),energyBefore=player.energy,hpBefore=player.hp;
    clearNavigation();removeItem('bread',1);
    player.energy=clamp(player.energy+Math.round(45+clamp(breadQuality-1,-.5,2)*8),0,player.maxEnergy);
    player.hp=clamp(player.hp+Math.round(10+clamp(breadQuality-1,-.5,2)*3),0,player.maxHp);
    world.minute+=180;
    while(world.minute>=1440){world.minute-=1440;world.day++;log(`Day ${world.day} begins. Prices and shortages have shifted.`,'world');for(const n of npcs)n.trust=clamp(n.trust-.03,0,10);}
    skillXp('fieldcraft',8);
    const energyGain=Math.round(player.energy-energyBefore),hpGain=Math.round(player.hp-hpBefore);
    log(`You made camp in ${zone.name}, ate Brown Bread, and rested for three hours.`,'world');
    save();renderUI();toast(`Camp rested · +${energyGain} energy · +${hpGain} health`);return true;
  }

  function nearestNPC(range=70){let best=null,bd=range;for(const n of npcs){const d=dist(player,n);if(d<bd){best=n;bd=d;}}return best;}
  function nearestResource(range=44){let best=null,bd=range;for(const r of world.resources){if(!r.available)continue;const d=dist(player,r);if(d<bd){best=r;bd=d;}}return best;}
  function nearestLandmark(range=50){let best=null,bd=range;for(const l of world.landmarks||[]){const d=dist(player,l);if(d<bd){best=l;bd=d;}}return best;}
  function claimStonepineWaycache(l){if(!l)return false;if(l.claimed){toast('Stonepine Waycache ready for field storage');return true;}const danger=world.enemies.find(e=>!e.dead&&(dist(l,e)<=180||dist(player,e)<=180));if(danger){toast(`${danger.name||'A wolf'} is too close to open the Stonepine Waycache`);return false;}l.discovered=true;l.claimed=true;l.guardsCleared=true;normalizeWaycacheStash(l);player.discoveries=Math.max(0,Number(player.discoveries||0))+1;addItem('arrows',8,1.6);addItem('bread',1,1.6);player.coins+=10;skillXp('fieldcraft',12);log('You secured the Stonepine Waycache: Trail Arrows, Brown Bread, and 10c for the return journey.','world');save();toast('Stonepine Waycache secured · arrows · bread · 10c');return true;}
  function waycacheTransferReady(l){if(!l?.claimed){toast('Secure the Stonepine Waycache before using its field stash');return false;}if(dist(player,l)>55){toast('Stand beside the Stonepine Waycache to move supplies');return false;}return true;}
  function waycacheStoreItem(l,id){if(!waycacheTransferReady(l))return false;if(!waycacheStorable(id)||itemCount(id)<1){toast('That supply cannot be stored in the Waycache');return false;}const weight=waycacheStashWeight(l),unit=Math.max(0,Number(itemDefs[id].weight)||0);if(weight+unit>WAYCACHE_CAPACITY+1e-9){toast('Stonepine Waycache is full · 12 weight maximum');return false;}const quality=avgQuality(id),stash=normalizeWaycacheStash(l),slot=stash[id]||(stash[id]={qty:0,qualitySum:0});if(!removeItem(id,1))return false;slot.qty+=1;slot.qualitySum+=quality;save();renderUI();toast(`Stored 1 ${itemDefs[id].name} · ${waycacheStashWeight(l).toFixed(1)}/${WAYCACHE_CAPACITY} weight`);return true;}
  function waycacheTakeItem(l,id){if(!waycacheTransferReady(l))return false;const stash=normalizeWaycacheStash(l),slot=stash[id];if(!waycacheStorable(id)||!slot?.qty){toast('That supply is not in the Waycache');return false;}const quality=slot.qualitySum/slot.qty;if(!addItem(id,1,quality))return false;slot.qty-=1;slot.qualitySum=Math.max(0,slot.qualitySum-quality);if(slot.qty<=0)delete stash[id];save();renderUI();toast(`Took 1 ${itemDefs[id].name} · ${waycacheStashWeight(l).toFixed(1)}/${WAYCACHE_CAPACITY} weight`);return true;}
  function moonwellIsNight(){return world.minute>=19*60||world.minute<6*60;}
  function moonwellNightKey(){return Math.max(0,world.minute<6*60?world.day-1:world.day);}
  function visitMoonwellHollow(l){if(!l)return false;let newlyDiscovered=false;if(!l.discovered){l.discovered=true;player.discoveries=Math.max(0,Number(player.discoveries||0))+1;skillXp('fieldcraft',10);log('You charted Moonwell Hollow in Moss Fen. Its pale water looks different after dusk.','world');newlyDiscovered=true;}if(!moonwellIsNight()){save();toast(newlyDiscovered?'Moonwell Hollow charted · return after dusk':'Moonwell Hollow is quiet until dusk');return true;}const night=moonwellNightKey();if(l.lastHarvestNight===night){save();toast('Moonwell Hollow has already been gathered this night');return true;}l.lastHarvestNight=night;addItem('mooncap',2,2.8);skillXp('herbcraft',6);log('Moonwell Hollow shimmered after dusk. You gathered two fine Mooncaps from the waterline.','world');save();toast('Moonwell harvest · 2 fine Mooncaps · Herbcraft +6 XP');return true;}
  function mineDeepQuarrySeam(l){if(!l)return false;if(!player.deeds?.emberback){toast('Emberback still blocks the Deep Quarry Seam');return false;}const pick=player.inventory.pick?normalizeArtifactSlot('pick',player.inventory.pick):null;if(player.equippedTool!=='pick'||!pick){toast('Equip a working Iron Pick to mine the Deep Quarry Seam');return false;}if(pick.durability<=0){toast('Your Iron Pick is broken — mend it before mining');return false;}if(player.energy<14){toast('Too tired to work the Deep Quarry Seam · need 14 energy');return false;}if(l.lastMinedDay===world.day){save();toast('Deep Quarry Seam already worked today · return tomorrow');return true;}const first=!l.discovered;if(first){l.discovered=true;player.discoveries=Math.max(0,Number(player.discoveries||0))+1;skillXp('fieldcraft',6);}player.energy-=14;pick.durability=Math.max(0,pick.durability-8);l.lastMinedDay=world.day;addItem('iron',2,2.6);skillXp('fieldcraft',6);log(`You worked the reopened Deep Quarry Seam and brought out two fine Iron Ore. Your pick took the strain.`,'world');save();renderUI();toast(`Deep Quarry Seam · 2 fine Iron Ore · pick ${Math.round(pick.durability)}/${Math.round(pick.maxDurability)}`);return true;}
  function discoverLandmark(l){if(!l)return false;if(l.id==='stonepine-trail-ledger')return visitStonepineLedger(l);if(l.id==='deep-quarry-seam')return mineDeepQuarrySeam(l);if(l.id==='moonwell-hollow')return visitMoonwellHollow(l);if(l.id==='stonepine-waycache')return claimStonepineWaycache(l);if(l.discovered){if(l.id==='stonepine-overlook')return eatBread();toast(`${l.name} is already charted`);return true;}l.discovered=true;player.discoveries=Math.max(0,Number(player.discoveries||0))+1;skillXp('fieldcraft',14);log(`You charted ${l.name}. The high ridge is now part of your field knowledge.`,'world');toast(`${l.name} charted · Fieldcraft +14 XP`);save();return true;}
  function nearestDrop(range=38){let best=null,bd=range;for(const d of world.drops){const dd=dist(player,d);if(dd<bd){best=d;bd=dd;}}return best;}
  function clearNavigation(){navigation.active=false;navigation.target=null;}
  function navigationEntity(target){if(!target)return null;if(target.kind==='npc')return npcs.find(n=>n.id===target.id)||null;if(target.kind==='resource')return world.resources.find(r=>r.id===target.id&&r.available)||null;if(target.kind==='landmark')return (world.landmarks||[]).find(l=>l.id===target.id)||null;if(target.kind==='drop')return world.drops.find(d=>d.id===target.id)||null;return null;}
  function navigationStop(target){return target?.kind==='npc'?62:target?.kind==='resource'?38:target?.kind==='landmark'?42:target?.kind==='drop'?30:7;}
  function interactNavigationTarget(target){if(!target)return false;if(target.kind==='npc'){const n=npcs.find(x=>x.id===target.id);if(n&&dist(player,n)<=70){renderNearby(n,true);return true;}}if(target.kind==='resource'){const r=world.resources.find(x=>x.id===target.id&&x.available);if(r&&dist(player,r)<=44)return gather(r);}if(target.kind==='landmark'){const l=(world.landmarks||[]).find(x=>x.id===target.id);if(l&&dist(player,l)<=50)return discoverLandmark(l);}if(target.kind==='drop'){const d=world.drops.find(x=>x.id===target.id);if(d&&dist(player,d)<=38){addItem(d.item,1,d.quality);world.drops=world.drops.filter(x=>x!==d);save();return true;}}return false;}
  function targetAtWorld(x,y){let best=null,bd=34;for(const n of npcs){const d=Math.hypot(n.x-x,n.y-y);if(d<bd){best={kind:'npc',id:n.id};bd=d;}}for(const r of world.resources){if(!r.available)continue;const d=Math.hypot(r.x-x,r.y-y);if(d<Math.min(bd,28)){best={kind:'resource',id:r.id};bd=d;}}for(const l of world.landmarks||[]){const d=Math.hypot(l.x-x,l.y-y);if(d<Math.min(bd,30)){best={kind:'landmark',id:l.id};bd=d;}}for(const drop of world.drops){const d=Math.hypot(drop.x-x,drop.y-y);if(d<Math.min(bd,28)){best={kind:'drop',id:drop.id};bd=d;}}return best;}
  function setNavigation(x,y,target=null){navigation.x=clamp(Number(x)||0,18,world.w-18);navigation.y=clamp(Number(y)||0,18,world.h-18);navigation.target=target;navigation.active=true;return{x:navigation.x,y:navigation.y,target:copy(target)};}
  function navigateToTarget(kind,id){const target={kind,id},entity=navigationEntity(target);if(!entity)return false;setNavigation(entity.x,entity.y,target);return true;}
  function interact(){clearNavigation();const n=nearestNPC();if(n){renderNearby(n,true);return true;}const l=nearestLandmark();if(l)return discoverLandmark(l);const r=nearestResource();if(r)return gather(r);const d=nearestDrop();if(d){addItem(d.item,1,d.quality);world.drops=world.drops.filter(x=>x!==d);save();return true;}toast('Nothing useful within reach');return false;}

  function armorRating(){const slot=player.inventory.jerkin;if(player.equippedArmor!=='jerkin'||!slot||slot.durability<=0)return 0;const q=avgQuality('jerkin');return q>=2.6?3:q>=1.7?2:1;}
  function takePlayerHit(amount){const absorbed=amount>2?Math.min(armorRating(),Math.max(0,amount-1)):0;if(absorbed>0)player.inventory.jerkin.durability=Math.max(0,player.inventory.jerkin.durability-2);player.hp=Math.max(0,player.hp-(amount-absorbed));if(absorbed>0){save();toast(`Wolfhide Jerkin absorbed ${absorbed} · ${Math.round(player.inventory.jerkin.durability)} durability left`);}return amount-absorbed;}
  function patchJerkin(){const slot=player.inventory.jerkin?normalizeArtifactSlot('jerkin',player.inventory.jerkin):null;if(!slot){toast('Craft a Wolfhide Jerkin before patching');return false;}if(slot.durability>=slot.maxDurability){toast('Wolfhide Jerkin is already fully patched');return false;}if(itemCount('hide')<1){toast('Patch Jerkin needs 1 Wolf Hide');return false;}const quality=avgQuality('hide'),before=slot.durability,repair=Math.round(30+player.skills.fieldcraft.level*4+clamp(quality-1,-.5,2)*6);removeItem('hide',1);slot.durability=Math.min(slot.maxDurability,slot.durability+repair);slot.provenance.repairs+=1;slot.provenance.history.push(`Patched by You on Day ${world.day} with ${qualityLabel(quality)} Wolf Hide.`);if(slot.provenance.history.length>8)slot.provenance.history.shift();skillXp('fieldcraft',4);save();renderUI();toast(`Wolfhide Jerkin patched +${Math.round(slot.durability-before)} · ${Math.round(slot.durability)}/${Math.round(slot.maxDurability)}`);return true;}

  function combatProfile(){const blade=player.inventory.blade,bow=player.inventory.bow,bladeReady=player.equippedWeapon==='blade'&&blade?.durability>0,bowFunctional=player.equippedWeapon==='bow'&&bow?.durability>0,arrows=itemCount('arrows'),bowReady=bowFunctional&&arrows>0,bladeQuality=bladeReady?avgQuality('blade'):1,bowQuality=bowFunctional?avgQuality('bow'):1;return{bladeReady,bowFunctional,bowReady,arrows,bladeQuality,bowQuality,range:bowReady?230:bladeReady?58:42,damage:bowReady?Math.round((13+player.skills.fieldcraft.level*2)*(1+(bowQuality-1)*.2)):bladeReady?Math.round((18+player.skills.guard.level*2)*(1+(bladeQuality-1)*.18)):9+player.skills.guard.level};}
  function releaseEmberbackBlockedWorkers(e){if(e?.type!=='emberback')return[];const released=[];for(const n of npcs){if(n.blockedByDanger?.enemyId!==e.id)continue;const report=n.blockedByDanger;n.blockedByDanger=null;n.trust=clamp(n.trust+.5,0,10);if(n.avoidEnemyId===e.id){n.avoidEnemyId=null;n.routeOverride=null;}memory(n,`Emberback fell; the Old Quarry is open again. I can return to ${itemDefs[report.itemId]?.name||'work'}.`);n.think=0;chooseNpcGoal(n);released.push(n.name);}if(released.length)log(`Emberback's fall reopened the Old Quarry. ${released.join(', ')} can return to work.`,'world');return released;}
