  function attack(){if(player.attackCd>0)return;const profile=combatProfile(),blade=player.inventory.blade,bow=player.inventory.bow,cost=profile.bowReady?5:4;if(player.equippedWeapon==='bow'&&profile.bowFunctional&&!profile.arrows){toast('No Trail Arrows — craft more before firing');return false;}if(player.energy<cost)return;player.attackCd=profile.bowReady?.62:.38;player.attackArc=.14;player.energy-=cost;if(player.equippedWeapon==='blade'&&blade&&!profile.bladeReady)toast('The Warden Blade is broken — fighting without its edge');if(player.equippedWeapon==='bow'&&bow&&!profile.bowFunctional)toast('The Briar Bow is broken — fighting without its range');let target=null,best=Infinity;for(const e of world.enemies){if(e.dead)continue;const d=dist(player,e);if(d>profile.range)continue;if(!profile.bowReady){target=e;break;}if(d<best){target=e;best=d;}}if(!target)return false;if(profile.bowReady)removeItem('arrows',1);target.hp-=profile.damage;skillXp(profile.bowReady?'fieldcraft':'guard',profile.bowReady?1:2);if(profile.bladeReady)blade.durability=Math.max(0,blade.durability-1);if(profile.bowReady)bow.durability=Math.max(0,bow.durability-1);if(profile.bowReady&&target.type==='briarwolf'&&target.windup>0&&target.hp>0){target.windup=0;target.pounce=0;target.stunned=Math.max(Number(target.stunned||0),.8);target.attackCd=Math.max(Number(target.attackCd||0),1.2);toast('Briar Bow interrupted the Briar Wolf pounce');}if(target.hp<=0){defeatEnemy(target);save();}else if(profile.bowReady)save();return true;}
