  function updateEnemy(e,dt){if(e.type==='emberback'){updateEmberback(e,dt);return;}if(e.type==='briarwolf'){updateBriarWolf(e,dt);return;}if(e.dead)return;if(!Number.isFinite(e.vx))e.vx=0;if(!Number.isFinite(e.vy))e.vy=0;e.attackCd=Math.max(0,e.attackCd-dt);const d=dist(player,e);if(d<230){const dx=player.x-e.x,dy=player.y-e.y,dd=Math.max(1,Math.hypot(dx,dy));e.x+=dx/dd*72*dt;e.y+=dy/dd*72*dt;if(dd<28&&e.attackCd<=0){e.attackCd=1.1;let dmg=10,defeated=false;if(player.guarded){dmg=1;player.guarded=false;e.hp-=6+player.skills.guard.level*2;toast('Brace held — countered');if(e.hp<=0)defeated=defeatEnemy(e);}takePlayerHit(dmg);if(player.hp<=0)recoverPlayerFromDefeat('You were carried back to Briar Glen. The wilds collected their price.');else if(defeated)save();}}else{e.wander-=dt;if(e.wander<=0){e.vx=rand(-1,1);e.vy=rand(-1,1);e.wander=rand(2,6);}e.x+=e.vx*18*dt;e.y+=e.vy*18*dt;}}

