  function setApprenticeEnabled(enabled,reason=''){const a=apprenticeState();a.enabled=!!enabled;a.plan=null;a.think=0;clearNavigation();if(a.enabled){a.goal='Choosing a useful next action';a.reason=reason||'Watching the same needs, risks, skills and relationships a player can see.';apprenticeRemember('Autonomous play started.');log('The Autonomous Apprentice takes the controls and begins choosing its own work.','world');}else{a.goal='Manual control';a.reason=reason||'You are in control.';if(reason)apprenticeRemember(reason);}renderApprentice();save();return a.enabled;}
  function manualTakeover(reason='You took control'){const a=apprenticeState();if(a.enabled)setApprenticeEnabled(false,reason);}
  function updateApprentice(dt){const a=apprenticeState();if(!a.enabled)return;if(a.plan){executeApprenticePlan(dt);return;}a.think-=dt;if(a.think<=0)chooseApprenticePlan();}
