  const keys=new Set();
  addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','KeyE','Digit1','Digit2','Digit3','Digit4','KeyQ'].includes(e.code))manualTakeover('Manual keyboard input took control.');if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))clearNavigation();keys.add(e.code);if(e.repeat)return;if(e.code==='Space')attack();if(e.code==='KeyE')interact();if(e.code==='Digit1')useSkill('fieldcraft');if(e.code==='Digit2')useSkill('smithing');if(e.code==='Digit3')useSkill('guard');if(e.code==='Digit4')useSkill('rapport');if(e.code==='KeyQ')drinkTonic();});
  addEventListener('keyup',e=>keys.delete(e.code));
  document.getElementById('attack-btn').addEventListener('click',()=>{manualTakeover('Manual attack took control.');attack();});document.getElementById('interact-btn').addEventListener('click',()=>{manualTakeover('Manual interaction took control.');interact();});document.getElementById('clear-log').addEventListener('click',()=>{world.events=[];renderLog();});UI.apprenticeToggle?.addEventListener('click',()=>setApprenticeEnabled(!apprenticeState().enabled,'You toggled autonomous play.'));
