    forceNpcNeed:(npcId,itemId)=>{const n=npcs.find(x=>x.id===npcId);if(!n||!itemDefs[itemId])return false;const otherMax=Math.max(0,...Object.keys(n.needBias||{}).filter(id=>id!==itemId).map(id=>npcNeedScore(n,id)));n.stock[itemId]=0;if(!isArtifact(itemId)){normalizeNpcStackQuality(n);delete n.stockQuality[itemId];}const deficit=isArtifact(itemId)?1:3;n.needBias[itemId]=(otherMax+10)/deficit;chooseNpcGoal(n);renderNearby(n,true);return true;},
    setNpcStock:(npcId,itemId,qty,quality=1)=>{const n=npcs.find(x=>x.id===npcId);if(!n||!itemDefs[itemId])return false;n.stock[itemId]=Math.max(0,Number(qty)||0);if(isArtifact(itemId)){if(n.stock[itemId]<=0&&n.stockMeta)delete n.stockMeta[itemId];}else{normalizeNpcStackQuality(n);if(n.stock[itemId]>0)n.stockQuality[itemId]=n.stock[itemId]*clamp(Number(quality)||1,.5,3);else delete n.stockQuality[itemId];}return true;},
    npcStockQuality:(npcId,itemId)=>{const n=npcs.find(x=>x.id===npcId);return n?npcStackQuality(n,itemId):null;},
