    setSkillLevel:(id,level)=>{if(!player.skills[id])return false;player.skills[id].level=clamp(Math.round(Number(level)||1),1,5);player.skills[id].xp=0;return player.skills[id].level;},
    setRelation:(npcId,otherId,value)=>{const n=npcs.find(x=>x.id===npcId),other=npcs.find(x=>x.id===otherId);if(!n||!other)return false;n.relations??={};n.relations[otherId]=clamp(Number(value)||0,-5,10);return n.relations[otherId];},
    smithEvidence:(npcId)=>{const n=npcs.find(x=>x.id===npcId);return n?smithEvidence(n):null;},
