    providerCallStatus:(npcId)=>{const n=npcs.find(x=>x.id===npcId);return n?copy(providerCallStatus(n)):null;},
    setDay:(day)=>{world.day=Math.max(1,Math.floor(Number(day)||1));return world.day;},
