    spawnBriarWolfAt:(x,y)=>spawnBriarWolf(Number(x)||0,Number(y)||0,false)?.id||null,
    enemies:()=>copy(world.enemies),
    spawnEmberbackAt:(x,y)=>spawnEmberback(Number(x)||335,Number(y)||430)?.id||null,
    enemy:(id)=>world.enemies.find(e=>e.id===id)||null,
    setEnemyHp:(id,value)=>{const e=world.enemies.find(x=>x.id===id);if(!e)return false;e.hp=clamp(Number(value)||0,0,e.maxHp);return e.hp;},
    drops:()=>copy(world.drops),
