    setDurability:(id,value)=>{const slot=player.inventory[id];if(!slot||slot.durability==null)return false;normalizeArtifactSlot(id,slot);slot.durability=clamp(Number(value)||0,0,slot.maxDurability);return slot.durability;},
    artifact:(id)=>artifactSnapshot(id),
    equip:(id)=>{if(!player.inventory[id])return false;if(itemDefs[id].kind==='tool')player.equippedTool=id;if(itemDefs[id].kind==='weapon')player.equippedWeapon=id;if(itemDefs[id].kind==='armor')player.equippedArmor=id;return true;},
