    advance:(seconds=1)=>{const steps=Math.max(1,Math.ceil(seconds/.1)),dt=seconds/steps;for(let i=0;i<steps;i++)update(dt);renderUI();save();return window.__BRIAR_GLEN_DEBUG__.snapshot();},
