  document.addEventListener('click',e=>{const target=e.target.closest?.('[data-craft]');if(target){manualTakeover('Manual crafting took control.');craft(target.dataset.craft);}});
  const craftBox=document.createElement('section');craftBox.className='card';craftBox.innerHTML='<div class="card-title"><span>Make</span><small>items exist to solve problems</small></div><div class="nearby"><button data-craft="tonic">Brew Tonic</button><button data-craft="pick">Forge Pick</button><button data-craft="blade">Forge Blade</button><button data-craft="bow">Craft Briar Bow</button><button data-craft="bedroll">Craft Trail Bedroll</button><button data-craft="jerkin">Craft Wolfhide Jerkin</button><button id="patch-jerkin">Patch Jerkin (1 hide)</button><button data-craft="arrows">Craft Trail Arrows ×6</button><button id="make-camp">Make Camp</button><button id="drink-tonic">Drink Tonic (Q)</button></div>';document.querySelector('.sidebar').insertBefore(craftBox,document.querySelector('.log-card'));document.getElementById('patch-jerkin').addEventListener('click',()=>{manualTakeover('Manual armor repair took control.');patchJerkin();});document.getElementById('make-camp').addEventListener('click',()=>{manualTakeover('Manual camping took control.');makeCamp();});document.getElementById('drink-tonic').addEventListener('click',()=>{manualTakeover('Manual tonic use took control.');drinkTonic();});

